import * as std from 'mbjs:std';
import * as os from 'mbjs:os';

let native = null;

function str(value) {
    if (Array.isArray(value)) return String(value[0] ?? '');
    return String(value ?? '');
}

function normalize(path) {
    return str(path).replace(/\\/g, '/');
}

function dirname(path) {
    const p = normalize(path);
    const i = p.lastIndexOf('/');
    if (i <= 0) return i === 0 ? '/' : '';
    return p.slice(0, i);
}

function basename(path) {
    const p = normalize(path);
    const i = p.lastIndexOf('/');
    return i < 0 ? p : p.slice(i + 1);
}

function join(...parts) {
    const out = [];
    for (const part of parts) {
        const p = normalize(part);
        if (!p) continue;
        if (out.length === 0) out.push(p.replace(/\/+$/, ''));
        else out.push(p.replace(/^\/+/, '').replace(/\/+$/, ''));
    }
    return out.join('/');
}

function currentDir() {
    return normalize(os.getcwd());
}

function fileExists(path) {
    try {
        const st = os.stat(normalize(path));
        if (Array.isArray(st))
            return st[0] !== null && st[0] !== undefined && Number(st[1] || 0) === 0;
        return !!st;
    } catch (e) {
        return false;
    }
}

function resolveNative(name) {
    const raw = str(name);
    const base = raw.replace(/\.(dll|so|dylib|lbrct)$/i, '');
    const exts = ['.dll', '.so', '.dylib', '.lbrct'];
    const dirs = [];
    let dir = currentDir();
    for (;;) {
        dirs.push(dir);
        const parent = dirname(dir);
        if (!parent || parent === dir || parent === '/') break;
        dir = parent;
    }
    for (const root of dirs) {
        for (const ext of exts) {
            const perMod = join(root, 'mochi_modules', base, 'lib', base + ext);
            if (fileExists(perMod)) return perMod;
            const file = join(root, 'mochi_modules', base + ext);
            if (fileExists(file)) return file;
            const bundled = join(root, 'node_modules', base, 'bin', base + ext);
            if (fileExists(bundled)) return bundled;
        }
    }
    return null;
}

const nativePath = resolveNative('mochifs');
if (nativePath) {
    try {
        native = await import(nativePath);
    } catch (e) {
        native = null;
    }
}

function modeOf(value, fallback) {
    const n = Number(value);
    return Number.isFinite(n) && n !== 0 ? n : fallback;
}

function statFromNative(raw) {
    const s = JSON.parse(raw);
    return {
        size: Number(s.size || 0),
        mtimeMs: Number(s.mtimeMs || 0),
        isDirectory: () => !!s.isDir,
        isFile: () => !!s.isFile,
        raw: s,
    };
}

function statFromOs(raw, path) {
    const s = Array.isArray(raw) ? raw[0] : raw;
    const status = Array.isArray(raw) ? Number(raw[1] || 0) : 0;
    if (!s || status !== 0) throw new Error(`ENOENT: ${path}`);
    const mode = Number(s.mode || 0);
    const isDir = !!(mode & 0x4000);
    return {
        size: Number(s.size || 0),
        mtimeMs: Number(s.mtime || 0),
        isDirectory: () => isDir,
        isFile: () => !!(mode & 0x8000),
        raw: s,
    };
}

export function existsSync(path) {
    const p = normalize(path);
    if (native) return Number(native.exists(p)) === 1;
    return fileExists(p);
}

export function readFileSync(path) {
    const p = normalize(path);
    if (native) return String(native.readText(p));
    const data = std.loadFile(p);
    if (data === undefined || data === null) throw new Error(`ENOENT: ${p}`);
    return String(data);
}

export function writeFileSync(path, data) {
    const p = normalize(path);
    const text = String(data ?? '');
    if (native) {
        native.writeText(p, text);
        return;
    }
    std.writeFile(p, text);
}

export function appendFileSync(path, data) {
    const p = normalize(path);
    const text = String(data ?? '');
    if (native) {
        native.appendText(p, text);
        return;
    }
    const old = existsSync(p) ? String(std.loadFile(p) ?? '') : '';
    std.writeFile(p, old + text);
}

export function statSync(path) {
    const p = normalize(path);
    if (native) {
        const raw = String(native.stat(p));
        if (!raw) throw new Error(`ENOENT: ${p}`);
        return statFromNative(raw);
    }
    return statFromOs(os.stat(p), p);
}

export function readdirSync(path) {
    const p = normalize(path);
    if (native) return JSON.parse(String(native.readdir(p)));
    const r = os.readdir(p);
    return Array.isArray(r) ? r[0] : r;
}

export function mkdirSync(path, options = {}) {
    const target = normalize(path);
    const mode = modeOf(options.mode, 0o755);
    if (!options.recursive) {
        if (native) native.mkdir(target);
        else os.mkdir(target, mode);
        return;
    }
    const parts = target.split('/');
    let current = '';
    for (let i = 0; i < parts.length; i++) {
        const part = parts[i];
        if (!part) {
            if (i === 0 && target.startsWith('/')) current = '/';
            continue;
        }
        if (/^[A-Za-z]:$/.test(part)) {
            current = part;
            continue;
        }
        current = current ? `${current}/${part}` : part;
        if (existsSync(current)) continue;
        try {
            if (native) native.mkdir(current);
            else os.mkdir(current, mode);
        } catch (e) {
            if (!existsSync(current)) throw e;
        }
    }
}

export function renameSync(from, to) {
    if (native) native.rename(normalize(from), normalize(to));
    else os.rename(normalize(from), normalize(to));
}

export function removeSync(path) {
    const p = normalize(path);
    if (native) native.remove(p);
    else os.remove(p);
}

export function copyFileSync(from, to) {
    const src = normalize(from);
    const dst = normalize(to);
    if (native) {
        native.copyFile(src, dst);
        return;
    }
    writeFileSync(dst, readFileSync(src));
}

export function cwd() {
    if (native) return String(native.cwd());
    return currentDir();
}

export function realpathSync(path) {
    const p = normalize(path);
    const r = os.realpath(p);
    return Array.isArray(r) ? String(r[0]) : String(r);
}

export async function readFile(path, options) {
    const data = readFileSync(path);
    if (options && typeof options === 'object' && options.encoding) return String(data);
    if (typeof options === 'string') return String(data);
    return data;
}
export async function writeFile(path, data) { return writeFileSync(path, data); }
export async function appendFile(path, data) { return appendFileSync(path, data); }
export async function stat(path) { return statSync(path); }
export async function readdir(path) { return readdirSync(path); }
export async function mkdir(path, options) { return mkdirSync(path, options); }
export async function rename(from, to) { return renameSync(from, to); }
export async function rm(path) { return removeSync(path); }
export async function unlink(path) { return removeSync(path); }
export async function copyFile(from, to) { return copyFileSync(from, to); }
export async function access(path) { if (!existsSync(path)) throw new Error('ENOENT: '+path); }

export const unlinkSync = removeSync;
export const rmSync = removeSync;
export const rmdirSync = removeSync;
export const promises = { readFile, writeFile, appendFile, stat, readdir, mkdir, rename, rm, unlink, copyFile, access };

export default {
    createReadStream,
    createWriteStream,
    watch,
    existsSync,
    readFileSync,
    writeFileSync,
    appendFileSync,
    statSync,
    readdirSync,
    mkdirSync,
    renameSync,
    removeSync,
    unlinkSync,
    rmSync,
    rmdirSync,
    copyFileSync,
    cwd,
    realpathSync,
    readFile,
    writeFile,
    promises,
};

import { Readable, Writable } from '../mochistream/index.js';
export function createReadStream(path, options={}) {
  const data = readFileSync(path);
  const chunk = typeof data === 'string' ? Buffer.from(data) : Buffer.from(data);
  return Readable.from([chunk]);
}
export function createWriteStream(path, options={}) {
  const chunks = [];
  return new Writable({
    write(chunk, enc, cb) { chunks.push(Buffer.from(chunk)); cb(); },
    final(cb) { try { writeFileSync(path, Buffer.concat(chunks)); cb(); } catch(e){ cb(e); } }
  });
}
export function watch() { return { on(){}, close(){} }; }
